mapper.select:
SELECT x.assessment_execution_id AS assessmentExecutionId, x.source_type AS sourceType, x.source_business_id AS sourceBusinessId, COALESCE(e.exam_name, CONCAT(course.course_name, ' / ', ci.item_title), JSON_UNQUOTE(JSON_EXTRACT(x.snapshot_json, '$.resource.name'))) AS sourceName, e.exam_id AS examId, e.exam_name AS examName, course.course_id AS courseId, course.course_name AS courseName, x.course_offering_id AS courseOfferingId, x.course_item_id AS courseItemId, ci.item_title AS courseItemTitle, c.exam_candidate_id AS examCandidateId, a.exam_attempt_id AS examAttemptId, a.attempt_no AS attemptNo, a.attempt_status AS attemptStatus, ans.exam_answer_id AS examAnswerId, q.attempt_question_id AS attemptQuestionId, q.question_type AS questionType, q.stem_snapshot AS stemSnapshot, q.score, ans.answer_text AS answerText, JSON_UNQUOTE(JSON_EXTRACT(q.correct_answer_snapshot_json, '$.standardAnswer')) AS standardAnswer, , a.submitted_time AS submittedTime, CASE WHEN ans.grading_status = 'PENDING_MANUAL' THEN 'PENDING' ELSE 'REVIEWED' END AS reviewStatus, rr.after_score AS latestManualScore, rr.review_comment AS latestReviewComment, rr.reviewed_time AS latestReviewedTime, CASE WHEN a.attempt_status = 'RESULT_EFFECTIVE' AND a.result_effective_time IS NOT NULL THEN 'EFFECTIVE' WHEN a.attempt_status = 'PUBLISHED' AND a.score_published_time IS NOT NULL THEN 'PUBLISHED' ELSE 'UNPUBLISHED' END AS scorePublishStatus, a.score_published_time AS scorePublishedTime FROM sts_exam_reviewer er JOIN sts_assessment_execution x ON x.assessment_execution_id = er.assessment_execution_id AND x.deleted = 0 LEFT JOIN sts_exam_exam e ON e.exam_id = x.exam_id AND e.deleted = 0 LEFT JOIN sts_course_offering co ON co.course_offering_id = x.course_offering_id AND co.deleted = 0 LEFT JOIN sts_course_course course ON course.course_id = co.course_id AND course.deleted = 0 LEFT JOIN sts_course_item ci ON ci.course_item_id = x.course_item_id AND ci.deleted = 0 JOIN sts_exam_attempt a ON a.assessment_execution_id = x.assessment_execution_id AND a.deleted = 0 JOIN sts_exam_candidate c ON c.exam_candidate_id = a.exam_candidate_id AND c.deleted = 0 LEFT JOIN us_sys_user u ON u.user_id = a.user_id AND u.deleted = 0 JOIN sts_exam_attempt_question q ON q.exam_attempt_id = a.exam_attempt_id AND (q.grading_mode = 'MANUAL' OR q.question_type = 'ESSAY') JOIN sts_exam_answer ans ON ans.exam_attempt_id = a.exam_attempt_id AND ans.attempt_question_id = q.attempt_question_id AND ans.deleted = 0 LEFT JOIN sts_org_organization org ON org.organization_id = c.organization_id AND org.deleted = 0 LEFT JOIN sts_exam_review_record rr ON rr.exam_answer_id = ans.exam_answer_id AND NOT EXISTS ( SELECT 1 FROM sts_exam_review_record newer WHERE newer.exam_answer_id = rr.exam_answer_id AND (newer.reviewed_time > rr.reviewed_time OR (newer.reviewed_time = rr.reviewed_time AND newer.review_record_id > rr.review_record_id)) ) WHERE er.reviewer_user_id = #{reviewerUserId}
AND x.source_type = 'COURSE_QUIZ' AND x.assessment_execution_id = #{assessmentExecutionId}
AND x.source_type IN ('STANDALONE_EXAM', 'STANDALONE_PRACTICE', 'TRAINING_EXAM')
AND a.attempt_status IN ('PENDING_REVIEW', 'PENDING_PUBLISH', 'PUBLISHED')
AND e.exam_id = #{query.examId}
AND ans.grading_status = 'PENDING_MANUAL'
AND ans.grading_status != 'PENDING_MANUAL'
AND 1 = 0
AND ( COALESCE(JSON_UNQUOTE(JSON_EXTRACT(c.candidate_profile_snapshot_json, '$.userName')), u.user_name) LIKE CONCAT('%', #{query.learnerKeyword}, '%') OR COALESCE(JSON_UNQUOTE(JSON_EXTRACT(c.candidate_profile_snapshot_json, '$.userCode')), u.user_code) LIKE CONCAT('%', #{query.learnerKeyword}, '%') )
AND a.submitted_time >= #{query.submittedStartTime}
AND a.submitted_time <= #{query.submittedEndTime}
ORDER BY CASE WHEN ans.grading_status = 'PENDING_MANUAL' THEN 0 ELSE 1 END, a.submitted_time, ans.exam_answer_id
